import os, math, argparse
from pyspark.sql import SparkSession, functions as F, types as T
EVENT_SCHEMA=T.StructType([T.StructField("ts",T.LongType()),T.StructField("type",T.StringType()),T.StructField("player",T.StringType()),T.StructField("uuid",T.StringType()),T.StructField("world",T.StringType()),T.StructField("x",T.IntegerType()),T.StructField("y",T.IntegerType()),T.StructField("z",T.IntegerType()),T.StructField("detail",T.StringType()),T.StructField("chat",T.StringType())])
ORE_WEIGHTS={"DIAMOND_ORE":10.0,"EMERALD_ORE":8.0,"GOLD_ORE":4.0,"IRON_ORE":2.0,"COAL_ORE":1.0,"REDSTONE_ORE":3.0,"LAPIS_ORE":3.0}
def chunk_expr(c): return F.floor(c/16).cast("int")
def write_metrics(df,checkpoint,bootstrap):
  return df.select(F.to_json(F.struct("ts","type","world","player","ore","count","value","chunk_x","chunk_z","active_players","flagged","ratio")).alias("value")).writeStream.format("kafka").option("kafka.bootstrap.servers",bootstrap).option("topic","minecraft-metrics").option("checkpointLocation",checkpoint).outputMode("update").start()
def jobs(spark,bootstrap,checkpoint_root):
 raw=spark.readStream.format("kafka").option("kafka.bootstrap.servers",bootstrap).option("subscribe","minecraft-events").option("startingOffsets","latest").load()
 e=raw.select(F.from_json(F.col("value").cast("string"),EVENT_SCHEMA).alias("e")).select("e.*").withColumn("event_time",F.to_timestamp(F.from_unixtime(F.col("ts")/1000))).withWatermark("event_time","2 minutes")
 ore=e.filter((F.col("type")=="block_break") & F.col("detail").isin(list(ORE_WEIGHTS)))
 ore_rates=ore.groupBy(F.window("event_time","1 minute"),"world","detail").count().select((F.col("window.end").cast("timestamp").cast("long")*1000).alias("ts"),F.lit("ore_rate").alias("type"),"world",F.lit(None).cast("string").alias("player"),F.col("detail").alias("ore"),F.col("count").cast("double").alias("count"),*[F.lit(None).cast("double").alias(x) for x in ["value","active_players","ratio"]],F.lit(None).cast("int").alias("chunk_x"),F.lit(None).cast("int").alias("chunk_z"))
 active=e.groupBy(F.window("event_time","30 seconds")).agg(F.approx_count_distinct("uuid").alias("active_players")).select((F.col("window.end").cast("timestamp").cast("long")*1000).alias("ts"),F.lit("active_players").alias("type"),*[F.lit(None).cast("string").alias(x) for x in ["world","player","ore"]],*[F.lit(None).cast("double").alias(x) for x in ["count","value"]],F.lit(None).cast("int").alias("chunk_x"),F.lit(None).cast("int").alias("chunk_z"),F.col("active_players").cast("double"),F.lit(None).cast("boolean").alias("flagged"),F.lit(None).cast("double").alias("ratio"))
 density=e.filter(F.col("x").isNotNull() & F.col("z").isNotNull()).groupBy(F.window("event_time","1 minute"),"world",chunk_expr(F.col("x")).alias("chunk_x"),chunk_expr(F.col("z")).alias("chunk_z")).count().select((F.col("window.end").cast("timestamp").cast("long")*1000).alias("ts"),F.lit("chunk_density").alias("type"),"world",*[F.lit(None).cast("string").alias(x) for x in ["player","ore"]],F.col("count").cast("double"),*[F.lit(None).cast("double").alias(x) for x in ["value","active_players","ratio"]],"chunk_x","chunk_z",F.lit(None).cast("boolean").alias("flagged"))
 weighted=ore.withColumn("weight",F.create_map(*sum(([F.lit(k),F.lit(v)] for k,v in ORE_WEIGHTS.items()),[]))[F.col("detail")]).groupBy(F.window("event_time","1 minute"),"world").agg(F.sum("weight").alias("value")).select((F.col("window.end").cast("timestamp").cast("long")*1000).alias("ts"),F.lit("economy_index").alias("type"),"world",*[F.lit(None).cast("string").alias(x) for x in ["player","ore"]],*[F.lit(None).cast("double").alias(x) for x in ["count"]],"value",F.lit(None).cast("int").alias("chunk_x"),F.lit(None).cast("int").alias("chunk_z"),*[F.lit(None).cast("double").alias(x) for x in ["active_players","ratio"]],F.lit(None).cast("boolean").alias("flagged"))
 suspicious=e.filter(F.col("type")=="block_break").groupBy(F.window("event_time","5 minutes"),"player").agg(F.sum(F.when(F.col("detail").isin(["DIAMOND_ORE","EMERALD_ORE"]),1).otherwise(0)).alias("rare"),F.count("*").alias("total")).withColumn("ratio",F.col("rare")/(F.col("total")+F.col("rare"))).withColumn("flagged",F.col("ratio")>0.35).select((F.col("window.end").cast("timestamp").cast("long")*1000).alias("ts"),F.lit("suspicious_mining").alias("type"),F.lit(None).cast("string").alias("world"),"player",*[F.lit(None).cast("string").alias(x) for x in ["ore"]],*[F.lit(None).cast("double").alias(x) for x in ["count","value"]],F.lit(None).cast("int").alias("chunk_x"),F.lit(None).cast("int").alias("chunk_z"),F.lit(None).cast("double").alias("active_players"),"flagged","ratio")
 return [write_metrics(x,f"{checkpoint_root}/{n}",bootstrap) for n,x in [("ore_rates",ore_rates),("active_players",active),("chunk_density",density),("economy_index",weighted),("suspicious_mining",suspicious)]]
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--bootstrap',default=os.getenv('KAFKA_BOOTSTRAP','localhost:9092'));ap.add_argument('--checkpoint-root',default='.spark_checkpoints');a=ap.parse_args();s=SparkSession.builder.appName('mc-telemetry').getOrCreate();q=jobs(s,a.bootstrap,a.checkpoint_root);s.streams.awaitAnyTermination()
